  1→import { useState } from "react";
  2→import { Button } from "@/components/ui/button";
  3→import { Badge } from "@/components/ui/badge";
  4→import { Checkbox } from "@/components/ui/checkbox";
  5→import { TableCell, TableRow } from "@/components/ui/table";
  6→import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
  7→import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
  8→import {
  9→  ChevronDown, ChevronUp, Phone, Mail, MapPin,
 10→  FileText, Archive
 11→} from "lucide-react";
 12→import { toast } from "sonner";
 13→import type { Result } from "@/pages/Index";
 14→import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
 15→
 16→// Sub-components
 17→import CandidateSummary from "@/components/candidate/CandidateSummary";
 18→import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
 19→import ExperiencePanel from "@/components/candidate/ExperiencePanel";
 20→import EducationPanel from "@/components/candidate/EducationPanel";
 21→import JDAlignedPanel from "@/components/candidate/JDAlignedPanel";
 22→import StrengthsGapsPanel from "@/components/candidate/StrengthsGapsPanel";
 23→import AINudgePanel from "@/components/candidate/AINudgePanel";
 24→import InterviewQuestionsPanel from "@/components/candidate/InterviewQuestionsPanel";
 25→import StageTracker from "@/components/candidate/StageTracker";
 26→import type { HiringStage } from "@/hooks/useStageTracker";
 27→
 28→interface CandidateRowProps {
 29→  result: Result;
 30→  index: number;
 31→  isExpanded: boolean;
 32→  isSelected: boolean;
 33→  jobTitle?: string | null;
 34→  onToggleRow: (id: string) => void;
 35→  onToggleSelect: (resumeId: string) => void;
 36→  onDownload: (filePath: string, filename: string) => void;
 37→  onDelete: (resumeId: string, filePath: string | null) => void;
 38→  onDismiss: (resumeId: string) => void;
 39→  formatCandidateName: (filename: string) => string;
 40→  currentStage?: HiringStage | null;
 41→  stageUpdatedAt?: string | null;
 42→  onStageChange?: (resumeId: string, stage: HiringStage) => void;
 43→}
 44→
 45→const getScoreColor = (score: number) => {
 46→  if (score >= 70) return "bg-score-skills";
 47→  if (score >= 40) return "bg-warning";
 48→  return "bg-destructive";
 49→};
 50→
 51→const getScoreTextColor = (score: number) => {
 52→  if (score >= 70) return "text-score-skills";
 53→  if (score >= 40) return "text-warning";
 54→  return "text-destructive";
 55→};
 56→
 57→const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
 58→  if (score >= 70) return { label: "Strong", variant: "success" };
 59→  if (score >= 40) return { label: "Good", variant: "warning" };
 60→  return { label: "Weak", variant: "destructive" };
 61→};
 62→
 63→const getRankDisplay = (index: number) => {
 64→  if (index < 3) {
 65→    const colors = [
 66→      "bg-score-overall text-white",
 67→      "bg-muted-foreground/60 text-white",
 68→      "bg-warning text-white",
 69→    ];
 70→    return (
 71→      <span className={`inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-bold ${colors[index]}`}>
 72→        {index + 1}
 73→      </span>
 74→    );
 75→  }
 76→  return (
 77→    <span className="inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-medium bg-muted text-muted-foreground">
 78→      {index + 1}
 79→    </span>
 80→  );
 81→};
 82→
 83→const CandidateRow = ({
 84→  result: r,
 85→  index,
 86→  isExpanded,
 87→  isSelected,
 88→  jobTitle,
 89→  onToggleRow,
 90→  onToggleSelect,
 91→  onDownload,
 92→  onDelete,
 93→  onDismiss,
 94→  formatCandidateName,
 95→  currentStage,
 96→  stageUpdatedAt,
 97→  onStageChange,
 98→}: CandidateRowProps) => {
 99→  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
100→  const strength = !r.pending ? getStrengthLabel(r.overall_score) : null;
101→
102→  return (
103→    <>
104→    <Collapsible open={isExpanded} onOpenChange={() => onToggleRow(r.id)} asChild>
105→      <>
106→        {/* Collapsed Row */}
107→        <TableRow className="cursor-pointer hover:bg-muted/50 transition-colors" onClick={() => !r.pending && onToggleRow(r.id)}>
108→          <TableCell onClick={(e) => e.stopPropagation()}>
109→            <Checkbox checked={isSelected} onCheckedChange={() => onToggleSelect(r.resume_id)} />
110→          </TableCell>
111→          <TableCell className="text-center">
112→            {r.pending ? <span className="text-sm text-muted-foreground">—</span> : getRankDisplay(index)}
113→          </TableCell>
114→          <TableCell className="font-medium">
115→            <div className="flex flex-col">
116→              <span className="text-sm">{r.candidate_name || formatCandidateName(r.filename)}</span>
117→              {r.candidate_location && (
118→                <span className="flex items-center gap-1 text-xs text-muted-foreground mt-0.5">
119→                  <MapPin className="h-3 w-3" /> {r.candidate_location}
120→                </span>
121→              )}
122→            </div>
123→          </TableCell>
124→          <TableCell>
125→            {r.pending ? (
126→              <Badge variant="outline" className="text-xs">Pending</Badge>
127→            ) : (
128→              <div className="flex items-center gap-2">
129→                <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden max-w-[100px]">
130→                  <div
131→                    className={`h-full rounded-full transition-all ${getScoreColor(r.overall_score)}`}
132→                    style={{ width: `${Math.min(r.overall_score, 100)}%` }}
133→                  />
134→                </div>
135→                <span className={`text-sm font-semibold tabular-nums min-w-[3ch] ${getScoreTextColor(r.overall_score)}`}>
136→                  {r.overall_score?.toFixed(0)}%
137→                </span>
138→              </div>
139→            )}
140→          </TableCell>
141→          <TableCell>
142→            <div className="flex flex-wrap items-center gap-1">
143→              {!r.pending && strength && (
144→                <Badge variant={strength.variant} className="text-[10px]">
145→                  {strength.label}
146→                </Badge>
147→              )}
148→              {!r.pending && currentStage && currentStage !== "applied" && (
149→                <Badge variant="outline" className="text-[10px] capitalize">
150→                  {currentStage}
151→                </Badge>
152→              )}
153→              {!r.pending && r.scoring_version === "heuristic" && (
154→                <TooltipProvider delayDuration={300}>
155→                  <Tooltip>
156→                    <TooltipTrigger asChild>
157→                      <span className="inline-flex items-center text-[10px] px-1.5 py-0.5 rounded bg-muted text-muted-foreground font-medium cursor-default">
158→                        Quick
159→                      </span>
160→                    </TooltipTrigger>
161→                    <TooltipContent className="max-w-xs text-xs">
162→                      This candidate was ranked by keyword matching. Top 20 candidates receive full AI scoring.
163→                    </TooltipContent>
164→                  </Tooltip>
165→                </TooltipProvider>
166→              )}
167→            </div>
168→          </TableCell>
169→          <TableCell>
170→            <div className="flex items-center gap-0.5" onClick={(e) => e.stopPropagation()}>
171→              <TooltipProvider delayDuration={300}>
172→                {/* Phone */}
173→                <Tooltip>
174→                  <TooltipTrigger asChild>
175→                    {r.candidate_phone ? (
176→                      <a
177→                        href={`tel:${r.candidate_phone}`}
178→                        onClick={(e) => {
179→                          if (!/Mobi|Android/i.test(navigator.userAgent)) {
180→                            e.preventDefault();
181→                            navigator.clipboard.writeText(r.candidate_phone!);
182→                            toast.success("Phone number copied!");
183→                          }
184→                        }}
185→                      >
186→                        <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary">
187→                          <Phone className="h-3.5 w-3.5" />
188→                        </Button>
189→                      </a>
190→                    ) : (
191→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
192→                        <Phone className="h-3.5 w-3.5" />
193→                      </Button>
194→                    )}
195→                  </TooltipTrigger>
196→                  <TooltipContent>{r.candidate_phone ? (/Mobi|Android/i.test(navigator.userAgent) ? r.candidate_phone : "Copy phone") : "No phone"}</TooltipContent>
197→                </Tooltip>
198→
199→                {/* Email */}
200→                <Tooltip>
201→                  <TooltipTrigger asChild>
202→                    {r.candidate_email ? (
203→                      <Button
204→                        variant="ghost"
205→                        size="icon"
206→                        className="h-7 w-7 text-muted-foreground hover:text-primary"
207→                        onClick={() => setEmailDialogOpen(true)}
208→                      >
209→                        <Mail className="h-3.5 w-3.5" />
210→                      </Button>
211→                    ) : (
212→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
213→                        <Mail className="h-3.5 w-3.5" />
214→                      </Button>
215→                    )}
216→                  </TooltipTrigger>
217→                  <TooltipContent>{r.candidate_email ? "Send email" : "No email"}</TooltipContent>
218→                </Tooltip>
219→
220→                {/* Download */}
221→                <Tooltip>
222→                  <TooltipTrigger asChild>
223→                    {r.file_path ? (
224→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary" onClick={() => onDownload(r.file_path!, r.filename)}>
225→                        <FileText className="h-3.5 w-3.5" />
226→                      </Button>
227→                    ) : (
228→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
229→                        <FileText className="h-3.5 w-3.5" />
230→                      </Button>
231→                    )}
232→                  </TooltipTrigger>
233→                  <TooltipContent>{r.file_path ? "Download resume" : "No file"}</TooltipContent>
234→                </Tooltip>
235→
236→                {/* Archive */}
237→                <Tooltip>
238→                  <TooltipTrigger asChild>
239→                    <Button
240→                      variant="ghost" size="icon"
241→                      className="h-7 w-7 text-muted-foreground hover:text-amber-500"
242→                      onClick={() => onDismiss(r.resume_id)}
243→                    >
244→                      <Archive className="h-3.5 w-3.5" />
245→                    </Button>
246→                  </TooltipTrigger>
247→                  <TooltipContent>Archive candidate</TooltipContent>
248→                </Tooltip>
249→              </TooltipProvider>
250→
251→              {!r.pending && (
252→                <CollapsibleTrigger asChild>
253→                  <Button variant="ghost" size="icon" className="h-7 w-7">
254→                    {isExpanded ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
255→                  </Button>
256→                </CollapsibleTrigger>
257→              )}
258→            </div>
259→          </TableCell>
260→        </TableRow>
261→
262→        {/* Expanded Detail — New Layout */}
263→        {!r.pending && (
264→          <CollapsibleContent asChild>
265→            <TableRow className="bg-muted/30 hover:bg-muted/30">
266→              <TableCell colSpan={6} className="p-5">
267→                <div className="space-y-4">
268→                  {/* 1. AI Summary */}
269→                  <CandidateSummary result={r} />
270→
271→                  {/* 2. Stage Tracker */}
272→                  {onStageChange && (
273→                    <StageTracker
274→                      currentStage={currentStage || "applied"}
275→                      updatedAt={stageUpdatedAt}
276→                      onStageChange={(stage) => onStageChange(r.resume_id, stage)}
277→                    />
278→                  )}
279→
280→                  {/* 3. Skills Detail | Experience | Education — 3 columns */}
281→                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
282→                    <SkillsDetailPanel result={r} />
283→                    <ExperiencePanel parsedJson={r.parsed_json} />
284→                    <EducationPanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves} />
285→                  </div>
286→
287→                  {/* 4. JD Aligned — full width */}
288→                  <JDAlignedPanel result={r} />
289→
290→                  {/* 5. Strengths & Gaps — full width */}
291→                  <StrengthsGapsPanel result={r} />
292→
293→                  {/* 6. AI Nudge */}
294→                  <AINudgePanel result={r} />
295→
296→                  {/* 7. Interview Questions — collapsible */}
297→                  <InterviewQuestionsPanel result={r} />
298→                </div>
299→              </TableCell>
300→            </TableRow>
301→          </CollapsibleContent>
302→        )}
303→      </>
304→    </Collapsible>
305→
306→    {r.candidate_email && (
307→      <EmailOutreachDialog
308→        open={emailDialogOpen}
309→        onOpenChange={setEmailDialogOpen}
310→        candidateName={r.candidate_name || r.filename}
311→        candidateEmail={r.candidate_email}
312→        jobTitle={jobTitle || "Open Position"}
313→        matchScore={Math.round(r.overall_score ?? 0)}
314→        resumeId={r.resume_id}
315→        jobId={r.id}
316→      />
317→    )}
318→    </>
319→  );
320→};
321→
322→export default CandidateRow;
323→

 1→import { Badge } from "@/components/ui/badge";
 2→import { Cpu, XCircle } from "lucide-react";
 3→import type { Result } from "@/pages/Index";
 4→
 5→interface SkillsDetailPanelProps {
 6→  result: Result;
 7→}
 8→
 9→const getSkillLevel = (score: number): { label: string; color: string } => {
10→  if (score >= 90) return { label: "Expert", color: "bg-emerald-500/10 text-emerald-600 border-emerald-200" };
11→  if (score >= 70) return { label: "Adv", color: "bg-blue-500/10 text-blue-600 border-blue-200" };
12→  if (score >= 50) return { label: "Mid", color: "bg-yellow-500/10 text-yellow-700 border-yellow-200" };
13→  if (score >= 25) return { label: "Low", color: "bg-orange-500/10 text-orange-600 border-orange-200" };
14→  return { label: "Gap", color: "bg-red-500/10 text-red-600 border-red-200" };
15→};
16→
17→const SkillsDetailPanel = ({ result: r }: SkillsDetailPanelProps) => {
18→  const scores = r.category_scores_json;
19→  const skillCount = scores ? Object.keys(scores).length : 0;
20→
21→  return (
22→    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
23→      <div className="flex items-center gap-2 mb-1">
24→        <div className="w-6 h-6 rounded bg-score-skills/10 flex items-center justify-center">
25→          <Cpu className="h-3.5 w-3.5 text-score-skills" />
26→        </div>
27→        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">Skills Detail</h4>
28→        {skillCount > 0 && (
29→          <Badge variant="outline" className="ml-auto text-[10px]">{skillCount} skills</Badge>
30→        )}
31→      </div>
32→
33→      {scores && typeof scores === "object" ? (
34→        <div className="space-y-2">
35→          {Object.entries(scores as Record<string, { score: number; notes?: string }>).map(([skill, data]) => {
36→            const level = getSkillLevel(data.score);
37→            return (
38→              <div key={skill} className="space-y-0.5">
39→                <div className="flex items-center justify-between text-xs gap-2">
40→                  <span className="text-muted-foreground capitalize truncate">{skill.replace(/_/g, " ")}</span>
41→                  <div className="flex items-center gap-1.5 shrink-0">
42→                    <span className="font-semibold tabular-nums">{data.score}%</span>
43→                    <span className={`text-[9px] font-medium px-1.5 py-0.5 rounded border ${level.color}`}>
44→                      {level.label}
45→                    </span>
46→                  </div>
47→                </div>
48→                <div className="h-1.5 rounded-full bg-secondary overflow-hidden">
49→                  <div
50→                    className="h-full rounded-full bg-score-skills transition-all"
51→                    style={{ width: `${Math.min(data.score, 100)}%` }}
52→                  />
53→                </div>
54→              </div>
55→            );
56→          })}
57→        </div>
58→      ) : (
59→        <p className="text-xs text-muted-foreground">No skill data available</p>
60→      )}
61→
62→      {r.missing_skills && r.missing_skills.length > 0 && (
63→        <div className="pt-1 space-y-1">
64→          <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-medium">Missing</span>
65→          <div className="flex flex-wrap gap-1">
66→            {r.missing_skills.map((skill, i) => (
67→              <span key={i} className="inline-flex items-center gap-0.5 text-[10px] px-1.5 py-0.5 rounded bg-destructive/10 text-destructive">
68→                <XCircle className="h-2.5 w-2.5" /> {skill}
69→              </span>
70→            ))}
71→          </div>
72→        </div>
73→      )}
74→    </div>
75→  );
76→};
77→
78→export default SkillsDetailPanel;
79→

 1→import { Badge } from "@/components/ui/badge";
 2→import { Briefcase } from "lucide-react";
 3→
 4→interface Role {
 5→  title?: string;
 6→  company?: string;
 7→  start?: string;
 8→  end?: string;
 9→  description?: string;
10→}
11→
12→interface ExperiencePanelProps {
13→  parsedJson: any;
14→}
15→
16→const ExperiencePanel = ({ parsedJson }: ExperiencePanelProps) => {
17→  const roles: Role[] = parsedJson?.roles_with_dates || parsedJson?.experience || [];
18→  const totalYears = roles.length > 0
19→    ? roles.reduce((sum, r) => {
20→        if (!r.start) return sum;
21→        const startYear = parseInt(r.start);
22→        const endYear = r.end && r.end.toLowerCase() !== "current" && r.end.toLowerCase() !== "present"
23→          ? parseInt(r.end)
24→          : new Date().getFullYear();
25→        return sum + Math.max(0, (endYear || 0) - (startYear || 0));
26→      }, 0)
27→    : null;
28→
29→  return (
30→    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
31→      <div className="flex items-center gap-2 mb-1">
32→        <div className="w-6 h-6 rounded bg-purple-500/10 flex items-center justify-center">
33→          <Briefcase className="h-3.5 w-3.5 text-purple-500" />
34→        </div>
35→        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">Experience</h4>
36→        {totalYears !== null && totalYears > 0 && (
37→          <Badge variant="outline" className="ml-auto text-[10px]">{totalYears} yrs</Badge>
38→        )}
39→      </div>
40→
41→      {roles.length > 0 ? (
42→        <div className="space-y-3">
43→          {roles.slice(0, 4).map((role, i) => {
44→            const duration = role.start && role.end
45→              ? `${role.start} – ${role.end}`
46→              : role.start || "";
47→            const isCurrentRole = role.end?.toLowerCase() === "current" || role.end?.toLowerCase() === "present";
48→
49→            return (
50→              <div key={i} className="flex gap-2">
51→                <div className="flex flex-col items-center mt-1">
52→                  <div className={`w-2 h-2 rounded-full shrink-0 ${i === 0 ? "bg-purple-500" : "bg-muted-foreground/40"}`} />
53→                  {i < Math.min(roles.length, 4) - 1 && <div className="w-px flex-1 bg-border mt-1" />}
54→                </div>
55→                <div className="space-y-0.5 min-w-0">
56→                  <p className="text-xs font-medium text-foreground leading-tight truncate">{role.title || "Untitled Role"}</p>
57→                  {role.company && (
58→                    <p className="text-[11px] text-muted-foreground truncate">{role.company}</p>
59→                  )}
60→                  <div className="flex items-center gap-1.5 flex-wrap">
61→                    {duration && <span className="text-[10px] text-muted-foreground">{duration}</span>}
62→                    {isCurrentRole && (
63→                      <Badge variant="outline" className="text-[9px] h-4 bg-emerald-500/10 text-emerald-600 border-emerald-200">Current</Badge>
64→                    )}
65→                  </div>
66→                </div>
67→              </div>
68→            );
69→          })}
70→          {roles.length > 4 && (
71→            <p className="text-[10px] text-muted-foreground">+{roles.length - 4} more roles</p>
72→          )}
73→        </div>
74→      ) : (
75→        <p className="text-xs text-muted-foreground">No experience data available</p>
76→      )}
77→    </div>
78→  );
79→};
80→
81→export default ExperiencePanel;
82→

 1→import { Badge } from "@/components/ui/badge";
 2→import { GraduationCap } from "lucide-react";
 3→
 4→interface Education {
 5→  degree?: string;
 6→  institution?: string;
 7→  year?: string;
 8→}
 9→
10→interface EducationPanelProps {
11→  parsedJson: any;
12→  matchedMustHaves?: string[];
13→}
14→
15→const EducationPanel = ({ parsedJson, matchedMustHaves }: EducationPanelProps) => {
16→  const education: Education[] = parsedJson?.education || [];
17→  const certifications: string[] = parsedJson?.certifications || [];
18→  const matchedLower = (matchedMustHaves || []).map((m: string) => m.toLowerCase());
19→
20→  const getRelevanceChip = (degree: string, institution: string) => {
21→    const combined = `${degree} ${institution}`.toLowerCase();
22→    const isMatched = matchedLower.some((m) => combined.includes(m) || m.includes("degree") || m.includes("education"));
23→    if (isMatched) return { label: "JD Match", color: "bg-emerald-500/10 text-emerald-600 border-emerald-200" };
24→    if (degree) return { label: "Relevant", color: "bg-blue-500/10 text-blue-600 border-blue-200" };
25→    return null;
26→  };
27→
28→  const matchCount = education.filter((e) => {
29→    const chip = getRelevanceChip(e.degree || "", e.institution || "");
30→    return chip?.label === "JD Match";
31→  }).length;
32→
33→  return (
34→    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
35→      <div className="flex items-center gap-2 mb-1">
36→        <div className="w-6 h-6 rounded bg-score-education/10 flex items-center justify-center">
37→          <GraduationCap className="h-3.5 w-3.5 text-score-education" />
38→        </div>
39→        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">Education</h4>
40→        {matchCount > 0 && (
41→          <Badge variant="outline" className="ml-auto text-[10px]">{matchCount} matched</Badge>
42→        )}
43→      </div>
44→
45→      {education.length > 0 ? (
46→        <div className="space-y-3">
47→          {education.slice(0, 4).map((edu, i) => {
48→            const chip = getRelevanceChip(edu.degree || "", edu.institution || "");
49→            return (
50→              <div key={i} className="space-y-0.5">
51→                <div className="flex items-start gap-1.5">
52→                  <GraduationCap className="h-3 w-3 text-muted-foreground shrink-0 mt-0.5" />
53→                  <div className="min-w-0">
54→                    <p className="text-xs font-medium text-foreground leading-tight">{edu.degree || "Degree"}</p>
55→                    {edu.institution && (
56→                      <p className="text-[11px] text-muted-foreground truncate">{edu.institution}</p>
57→                    )}
58→                    <div className="flex items-center gap-1.5 mt-0.5">
