 36→const ConfidenceReport = ({ results }: ConfidenceReportProps) => {
 37→  const [open, setOpen] = useState(false);
 38→
 39→  const scored = results.filter((r) => !r.pending && r.overall_score > 0);
 40→  if (scored.length === 0) return null;
 41→
 42→  // 1. Overall AI Confidence
 43→  const avgConfidence = Math.round(
 44→    scored.reduce((sum, r) => sum + (r.confidence ?? 0), 0) / scored.length
 45→  );
 46→
 47→  // 2. Per-Dimension averages from category_scores_json
 48→  const dimensionTotals: Record<string, { total: number; count: number }> = {};
 49→  for (const r of scored) {
 50→    if (!r.category_scores_json || typeof r.category_scores_json !== "object") continue;
 51→    for (const [key, val] of Object.entries(
 52→      r.category_scores_json as Record<string, { score: number }>
 53→    )) {
 54→      if (!dimensionTotals[key]) dimensionTotals[key] = { total: 0, count: 0 };
 55→      dimensionTotals[key].total += val.score ?? 0;
 56→      dimensionTotals[key].count += 1;
 57→    }
 58→  }
 59→  const dimensions = Object.entries(dimensionTotals).map(([name, { total, count }]) => ({
 60→    name,
 61→    avg: Math.round(total / count),
 62→  }));
 63→
 64→  // 3. Score distribution buckets
 65→  const buckets: BucketEntry[] = [
 66→    { label: "Weak", range: "0–25%", count: 0 },
 67→    { label: "Below Avg", range: "26–50%", count: 0 },
 68→    { label: "Good", range: "51–75%", count: 0 },
 69→    { label: "Strong", range: "76–100%", count: 0 },
 70→  ];
 71→  for (const r of scored) {
 72→    const s = r.overall_score;
 73→    if (s <= 25) buckets[0].count++;
 74→    else if (s <= 50) buckets[1].count++;
 75→    else if (s <= 75) buckets[2].count++;
 76→    else buckets[3].count++;
 77→  }
