  1→import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
  2→import { supabase } from "@/integrations/supabase/client";
  3→import { useAuth } from "@/hooks/useAuth";
  4→import { toast } from "sonner";
  5→
  6→export type HiringStage = "applied" | "screened" | "interview" | "offer" | "hired" | "rejected";
  7→
  8→export const STAGE_ORDER: HiringStage[] = ["applied", "screened", "interview", "offer", "hired"];
  9→
 10→export interface CandidateStage {
 11→  id: string;
 12→  resume_id: string;
 13→  job_id: string;
 14→  stage: HiringStage;
 15→  updated_at: string;
 16→}
 17→
 18→export function useStages(jobId: string | null) {
 19→  return useQuery({
 20→    queryKey: ["candidate-stages", jobId],
 21→    queryFn: async () => {
 22→      if (!jobId) return [];
 23→      const { data, error } = await (supabase as any)
 24→        .from("candidate_stages")
 25→        .select("id, resume_id, job_id, stage, updated_at")
 26→        .eq("job_id", jobId);
 27→      if (error) throw error;
 28→      return (data ?? []) as CandidateStage[];
 29→    },
 30→    enabled: !!jobId,
 31→  });
 32→}
 33→
 34→export function useUpdateStage() {
 35→  const queryClient = useQueryClient();
 36→  const { user } = useAuth();
 37→
 38→  return useMutation({
 39→    mutationFn: async ({
 40→      resumeId,
 41→      jobId,
 42→      newStage,
 43→      currentStage,
 44→    }: {
 45→      resumeId: string;
 46→      jobId: string;
 47→      newStage: HiringStage;
 48→      currentStage?: HiringStage | null;
 49→    }) => {
 50→      // Upsert the current stage
 51→      const { error: upsertError } = await (supabase as any)
 52→        .from("candidate_stages")
 53→        .upsert(
 54→          {
 55→            resume_id: resumeId,
 56→            job_id: jobId,
 57→            stage: newStage,
 58→            updated_at: new Date().toISOString(),
 59→            updated_by: user?.id,
 60→          },
 61→          { onConflict: "resume_id,job_id" }
 62→        );
 63→      if (upsertError) throw upsertError;
 64→
 65→      // Log the transition
 66→      const { error: historyError } = await (supabase as any)
 67→        .from("stage_history")
 68→        .insert({
 69→          resume_id: resumeId,
 70→          job_id: jobId,
 71→          from_stage: currentStage || null,
 72→          to_stage: newStage,
 73→          changed_by: user?.id,
 74→        });
 75→      if (historyError) throw historyError;
 76→    },
 77→    onSuccess: (_, variables) => {
 78→      queryClient.invalidateQueries({ queryKey: ["candidate-stages", variables.jobId] });
 79→    },
 80→    onError: (error: Error) => {
 81→      toast.error(error.message || "Failed to update stage");
 82→    },
 83→  });
 84→}
 85→
 86→export function useStageSummary(jobId: string | null) {
 87→  const { data: stages } = useStages(jobId);
 88→
 89→  const summary: Record<HiringStage, number> = {
 90→    applied: 0,
 91→    screened: 0,
 92→    interview: 0,
 93→    offer: 0,
 94→    hired: 0,
 95→    rejected: 0,
 96→  };
 97→
 98→  if (stages) {
 99→    stages.forEach((s) => {
100→      if (summary[s.stage] !== undefined) {
101→        summary[s.stage]++;
102→      }
103→    });
104→  }
105→
106→  return summary;
107→}
