  1→import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
  2→import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
  3→
  4→const corsHeaders = {
  5→  "Access-Control-Allow-Origin": "*",
  6→  "Access-Control-Allow-Headers":
  7→    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
  8→};
  9→
 10→const OPENAI_API_KEY = Deno.env.get("OPENAI_API_KEY")!;
 11→const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 12→const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 13→
 14→serve(async (req) => {
 15→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 16→
 17→  try {
 18→    // Auth check
 19→    const authHeader = req.headers.get("Authorization");
 20→    if (!authHeader) throw new Error("No auth header");
 21→
 22→    const token = authHeader.replace("Bearer ", "");
 23→    const anonKey = Deno.env.get("SUPABASE_PUBLISHABLE_KEY") || Deno.env.get("SUPABASE_ANON_KEY")!;
 24→    const supabaseUser = createClient(SUPABASE_URL, anonKey, {
 25→      global: { headers: { Authorization: authHeader } },
 26→    });
 27→    const { data: claimsData, error: claimsError } = await supabaseUser.auth.getClaims(token);
 28→    if (claimsError || !claimsData?.claims) throw new Error("Unauthorized");
 29→    const user = { id: claimsData.claims.sub as string };
 30→
 31→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 32→
 33→    const { job_id } = await req.json();
 34→    if (!job_id) throw new Error("Missing job_id");
 35→
 36→    // Verify ownership and fetch JD
 37→    const { data: job } = await supabase
 38→      .from("jobs")
 39→      .select("id, job_description, user_id")
 40→      .eq("id", job_id)
 41→      .single();
 42→
 43→    if (!job) throw new Error("Job not found");
 44→    if (job.user_id !== user.id) throw new Error("Unauthorized");
 45→
 46→    const jdText: string = job.job_description || "";
 47→
 48→    // Guard: refuse if JD is too short
 49→    if (jdText.trim().length < 50) {
 50→      throw new Error("Job description is too short to rewrite (minimum 50 characters).");
 51→    }
 52→
 53→    // Deduct 1 credit before calling OpenAI
 54→    const { error: deductError } = await supabase.rpc("deduct_credits", {
 55→      p_user_id: user.id,
 56→      p_amount: 1,
 57→    });
 58→    if (deductError) throw new Error("Insufficient credits or failed to deduct credits.");
 59→
 60→    // Single LLM call: rewrite + score the original JD
 61→    const systemPrompt = `You are an expert technical recruiter and job description specialist. Your task is to:
 62→1. Rewrite the provided job description for maximum clarity, ATS optimization, and inclusive language.
 63→2. Score the ORIGINAL job description (before rewriting) on 4 dimensions.
 64→3. Identify important keywords and whether they appear in the original.
 65→
 66→REWRITING GUIDELINES:
 67→- Use clear, concise language. Avoid jargon unless it is a required technical term.
 68→- Structure with clear sections: Role Summary, Responsibilities, Requirements (Must-Have), Nice to Have, and Benefits (if present).
 69→- Use inclusive language: avoid gendered words, age indicators, or unnecessarily exclusionary phrasing.
 70→- Ensure ATS-friendly formatting: use standard section headers, bullet points, and spell out acronyms on first use.
 71→- Preserve all original requirements — do not add or remove skills/qualifications.
 72→- Keep the same general tone (technical, professional, etc.) as the original.
 73→
 74→SCORING GUIDELINES (score the ORIGINAL JD, 0–100 each):
 75→- clarity: How clearly written and structured is the JD? (0=incomprehensible, 100=extremely clear)
 76→- keywords: How well does the JD include relevant industry keywords for ATS? (0=almost none, 100=comprehensive)
 77→- ats_fit: How well formatted is the JD for ATS systems? (0=very poor, 100=excellent)
 78→- inclusivity: How inclusive and bias-free is the language? (0=highly exclusive, 100=fully inclusive)
 79→
 80→MISSING KEYWORDS: List 8–12 important keywords/skills. For each, indicate if it was "detected" in the original JD or "missing".
 81→
 82→Return ONLY valid JSON with this exact structure:
 83→{
 84→  "rewritten_jd": "...",
 85→  "quality_score": {
 86→    "overall": <number 0-100, average of the 4 scores>,
 87→    "clarity": <number 0-100>,
 88→    "keywords": <number 0-100>,
 89→    "ats_fit": <number 0-100>,
 90→    "inclusivity": <number 0-100>
 91→  },
 92→  "missing_keywords": [
 93→    { "keyword": "...", "status": "missing" | "detected" }
 94→  ]
 95→}`;
 96→
 97→    const response = await fetch("https://api.openai.com/v1/chat/completions", {
 98→      method: "POST",
 99→      headers: {
100→        Authorization: `Bearer ${OPENAI_API_KEY}`,
101→        "Content-Type": "application/json",
102→      },
103→      body: JSON.stringify({
104→        model: "gpt-4o",
105→        messages: [
106→          { role: "system", content: systemPrompt },
107→          { role: "user", content: `JOB DESCRIPTION TO ANALYZE AND REWRITE:\n\n${jdText.slice(0, 8000)}` },
108→        ],
109→        response_format: { type: "json_object" },
110→        temperature: 0.3,
111→      }),
112→    });
113→
114→    if (!response.ok) {
115→      const errBody = await response.text();
116→      throw new Error(`OpenAI API error ${response.status}: ${errBody.slice(0, 200)}`);
117→    }
118→
119→    const aiData = await response.json();
120→    const content = aiData.choices?.[0]?.message?.content;
121→    if (!content) throw new Error("OpenAI returned empty response");
122→
123→    const parsed = JSON.parse(content);
124→
125→    if (!parsed.rewritten_jd || !parsed.quality_score || !Array.isArray(parsed.missing_keywords)) {
126→      throw new Error("Unexpected response structure from OpenAI");
127→    }
128→
129→    // Store results in jobs table
130→    const { error: updateError } = await supabase
131→      .from("jobs")
132→      .update({
133→        rewritten_jd: parsed.rewritten_jd,
134→        jd_quality_score: parsed.quality_score,
135→      } as any)
136→      .eq("id", job_id);
137→
138→    if (updateError) throw new Error(`Failed to save rewrite results: ${updateError.message}`);
139→
140→    console.log(`JD rewrite complete for job ${job_id}`);
141→
142→    return new Response(
143→      JSON.stringify({
144→        success: true,
145→        rewritten_jd: parsed.rewritten_jd,
146→        quality_score: parsed.quality_score,
147→        missing_keywords: parsed.missing_keywords,
148→      }),
149→      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
150→    );
151→  } catch (err) {
152→    console.error("rewrite-jd error:", err);
153→    return new Response(
154→      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
155→      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
156→    );
157→  }
158→});
